import {interests,interestDescription,catalogueSummary} from './interests.mjs';
import {countryMatches,destinationOptions} from './destinations.mjs';
import {subjectMatches} from './subjects.mjs';
import {translateText,localizeDOM,searchAliases} from './localize.mjs';
import {translations} from './i18n.mjs';
import {regions,coverageLabels,testLabels,money,enrich,filterRoutes,deadlineState,addComparison,safeStored,safeSave} from './logic.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Unavailable');}};}
const prefs=safeStored(storage,'divergents.preferences',{});
let lang=['en','kk','ru'].includes(prefs.lang)?prefs.lang:'en',year=+prefs.year||2027;
let saved=safeStored(storage,'divergents.shortlist',[]),compare=safeStored(storage,'divergents.compare',[]),page='explore',selected=null,onlySaved=false;
let f={fields:[],year,costUnknown:true,testUnknown:false};
const d=await fetch('./catalogue.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json();}).catch(e=>{$('#main').innerHTML='<div class="empty">The catalogue could not load. Please reload this page.</div>';localizeDOM($('#main'),lang);throw e;});
const routes=enrich(d);saved=Array.isArray(saved)?saved.filter(id=>routes.some(r=>r.id===id)):[];compare=Array.isArray(compare)?compare.filter(id=>routes.some(r=>r.id===id)).slice(0,3):[];
const t=k=>translations[lang][k]||translations.en[k]||k;
function localize(root=document.body){localizeDOM(root,lang);}
const tr=value=>translateText(value,lang);
for(const r of routes)r.searchAliases=searchAliases(r);
function persist(){safeSave(storage,'divergents.preferences',{lang,year});}
function toast(message){$('#toast').textContent=tr(message);$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function storeList(){if(!safeSave(storage,'divergents.shortlist',saved)||!safeSave(storage,'divergents.compare',compare))toast('Browser storage unavailable. Changes will last for this visit only.');}
function btn(action,label,cls='',attrs=''){return `<button type="button" data-action="${action}" class="${cls}" ${attrs}>${label}</button>`;}
function options(values,current,any=t('all')){return `<option value="">${esc(any)}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function header(){document.documentElement.lang=lang;document.title=tr('Divergents · Find your next direction');document.querySelector('meta[name=description]').content=tr('Explore colleges and universities after Grade 9 or Grade 11 with Divergents. Search, save and compare your options.');$('.skip').textContent=tr('Skip to content');$('#header').innerHTML=`<a class="brand" href="#" data-action="home"><span class="brandmark">d<span>↗</span></span><span>DIVERGENTS</span></a><nav aria-label="Main navigation">${['explore','shortlist','compare'].map(p=>btn('page',`${t(p)}${p==='shortlist'?` <span class="count">${saved.length}</span>`:''}`,page===p?'active':'',`data-page="${p}" aria-current="${page===p?'page':'false'}"`)).join('')}</nav><label class="language"><span class="sr">Interface language</span><select id="lang"><option value="en" ${lang==='en'?'selected':''}>EN</option><option value="kk" ${lang==='kk'?'selected':''}>ҚАЗ</option><option value="ru" ${lang==='ru'?'selected':''}>РУС</option></select></label>`;}
function hero(){return `<section class="hero simple-hero"><div class="hero-content"><h1>Where would you like to study?</h1><div class="pathway-choices" role="group" aria-label="Choose an entry pathway">${btn('entry','After Grade 9','pathway-choice '+(f.stage==='9'?'selected':''),'data-stage="9" aria-pressed="'+(f.stage==='9')+'"')}${btn('entry','After Grade 11','pathway-choice '+(f.stage==='11'?'selected':''),'data-stage="11" aria-pressed="'+(f.stage==='11')+'"')}${btn('entry','All options','pathway-choice '+(!f.stage?'selected':''),'data-stage="" aria-pressed="'+(!f.stage)+'"')}</div></div></section>`;}
function selectFilter(id,label,vals,current){return `<label>${label}<select id="${id}" data-filter="${id}">${options(vals,current)}</select></label>`;}
function filters(){const selected=f.fields[0]||'';return `<aside class="filters" aria-label="${t('filters')}"><label>${t('country')}<select id="country" data-filter="country"><option value="">${t('all')}</option>${destinationOptions(lang).map(row=>`<option data-no-i18n value="${row.code}" ${f.country===row.code?'selected':''}>${esc(row.labels[lang])}</option>`).join('')}</select></label><label>What interests you?<select id="subject" data-filter="subject" aria-describedby="subject-help"><option value="">All interests</option>${interests.map(row=>`<option data-no-i18n value="${row.id}" ${selected===row.id?'selected':''}>${esc(row.labels[lang])}</option>`).join('')}</select><span id="subject-help" class="subject-help" data-no-i18n ${!selected?'hidden':''}>${esc(interestDescription(selected,lang))}</span></label>${btn('reset',t('reset'),'text-btn reset-simple')}</aside>`;}
function routeCard(r){const multiple=routes.filter(x=>x.programmeId===r.programmeId&&x.entryAfter===r.entryAfter).length>1;return `<article class="route-card"><div class="card-top"><span class="tag ${r.i.region==='Kazakhstan'?'green':''}">${esc(r.i.country)} · ${r.entryAfter===9?'After Grade 9':'After Grade 11'}</span>${btn('save',saved.includes(r.id)?'♥':'♡','bookmark',`data-id="${r.id}" aria-label="${saved.includes(r.id)?t('remove'):t('save')} ${esc(r.p.name)} ${esc(r.name)}" aria-pressed="${saved.includes(r.id)}"`)}</div><p class="institution">${esc(r.i.name)} · ${esc(r.i.city)}</p><h3>${esc(r.p.name)}</h3>${multiple?`<p class="route-name">${esc(r.name)}</p>`:''}<div class="simple-price"><small>Tuition reference</small><strong>${esc(money(r.tuition,lang))}</strong></div><div class="card-footer">${btn('detail','Details ↗','primary',`data-id="${r.id}"`)}${btn('compare',`${compare.includes(r.id)?'✓':'+ '}${t('compare')}`,'compare-btn',`data-id="${r.id}" aria-pressed="${compare.includes(r.id)}"`)}</div></article>`;}
function explorer(){return `${hero()}<div class="page-body"><section class="catalogue" id="catalogue"><div class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" id="search" value="${esc(f.q)}" placeholder="${t('search')}" aria-label="${t('search')}"></div><div class="catalogue-layout">${filters()}<div><div class="result-bar"><strong id="resultCount"></strong></div><div class="active-filters" id="activeFilters"></div><div id="results" class="results"></div></div></div></section></div>`;}
function renderResults(){const list=filterRoutes(routes,{...f,year});$('#resultCount').textContent=catalogueSummary(list,lang);$('#activeFilters').innerHTML=f.region?`<span>${esc(f.region)}</span>`:'';const regionEmpty=f.region&&!routes.some(r=>r.i.region===f.region);const countryGap=f.country&&!routes.some(r=>countryMatches(r.i.country,f.country));const subjectGap=f.fields.length&&!routes.some(r=>f.fields.some(field=>subjectMatches(r.p,field)));$('#results').innerHTML=list.length?list.map(routeCard).join(''):`<div class="empty"><span>↗</span><h3>${countryGap?'No verified programmes for this destination yet':subjectGap?'No verified programmes in this subject yet':regionEmpty?'Verified coverage is still growing here':t('empty')}</h3><p>${countryGap||subjectGap?'The filter list is complete; the verified programme catalogue is still growing.':regionEmpty?'This region is part of our worldwide catalogue model. A reviewer still needs to verify accessible routes.':t('emptyHelp')}</p>${btn('reset',t('reset'),'primary')}${btn('page',t('coverage'),'text-btn','data-page="coverage"')}</div>`;if($('#subject-help')){$('#subject-help').textContent=interestDescription(f.fields[0],lang);$('#subject-help').hidden=!f.fields.length;}localize($('#results'));localize($('#resultCount'));localize($('#activeFilters'));}
function pageTitle(k,sub){return `<div class="page-title"><span class="eyebrow">DIVERGENTS EXPLORER</span><h1>${t(k)}</h1><p>${sub}</p></div>`;}
function shortlistPage(){return `<div class="page-body">${pageTitle('shortlist',t('local'))}<div class="results wide">${saved.length?saved.map(id=>routeCard(routes.find(r=>r.id===id))).join(''):`<div class="empty"><h2>A little curiosity goes a long way.</h2><p>Save any applicant route with the heart button. Come back here to compare your next steps.</p>${btn('page',t('explore'),'primary','data-page="explore"')}</div>`}</div></div>`;}
function deadlineHtml(x){const state=deadlineState(x,year);return `<article class="deadline"><div><span class="tag ${state==='Confirmed for selected cycle'?'green':''}">${esc(x.type)} · ${esc(state)}</span><h4>${esc(x.label)}</h4><strong>${x.date?esc(x.date):'Date awaiting publication'} ${x.time?esc(x.time):''} ${x.timezone?`· ${esc(x.timezone)}`:'· timezone not published'}</strong><p>Cycle: ${esc(x.cycle)} · ${esc(x.applicant)}</p><p><b>${t('next')}:</b> ${esc(x.nextAction)}</p>${sourceList(x.sourceIds)}</div></article>`;}
function calendarPage(){let ds=d.deadlines.filter(x=>!onlySaved||x.routeIds.some(id=>saved.includes(id))).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));const pending=routes.filter(r=>(!onlySaved||saved.includes(r.id))&&!r.deadlines.some(x=>String(x.cycle).startsWith(String(year))&&x.status!=='historical'));return `<div class="page-body narrow">${pageTitle('calendar','Admission, funding, tests and documents each have their own clock.')}<div class="calendar-controls"><label>${t('year')}<input type="number" id="year" min="2026" max="2040" value="${year}"></label><label class="check"><input type="checkbox" id="onlySaved" ${onlySaved?'checked':''}> Shortlisted routes only</label></div><div class="notice">${pending.length} route(s) have no confirmed deadlines in the selected ${year} cycle. <strong>Awaiting confirmation</strong> — no dates have been moved forward.</div><p class="context-note">Historical records and other cycles remain below as references. A source may use an academic-year label while its deadline falls in the preceding calendar year.</p>${ds.length?ds.map(deadlineHtml).join(''):'<div class="empty">No sourced deadline records for this selection. Check each official admissions page.</div>'}<details class="pending-routes"><summary>Routes awaiting ${year} deadline confirmation (${pending.length})</summary>${pending.map(r=>`<p>${btn('detail',`${esc(r.i.name)} · ${esc(r.p.name)} · ${esc(r.name)}`,'text-btn',`data-id="${r.id}"`)}<small>${esc(r.nextAction)}</small></p>`).join('')}</details></div>`;}
function sourceList(ids){return `<ul class="sources">${[...new Set(ids||[])].map(id=>{const s=d.sources.find(s=>s.id===id);return s?`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small>${t('checked')} ${esc(s.checked)} · ${esc(s.cycle)} · ${esc(s.status)}<br>${esc(s.applicant)}${s.note?`<br>${esc(s.note)}`:''}</small></li>`:'';}).join('')}</ul>`;}
function testsHtml(r){return `<dl class="tests">${Object.entries(r.tests).map(([key,value])=>`<div><dt>${key==='UNT'?'ЕНТ / ҰБТ / UNT':key==='ENGLISH'?'English evidence':key==='PSYCHOMETRIC'?'Psychometric assessment':key==='PEDAGOGICAL'?'Teaching aptitude assessment':esc(key)}<span class="status ${value.status}">${testLabels[value.status]||'Awaiting verification'}</span></dt><dd>${esc(value.detail)}</dd></div>`).join('')}</dl>`;}
function awardsHtml(r){return r.awards.length?r.awards.map(a=>`<article class="award"><span class="tag green">${esc(coverageLabels[a.coverage])}</span><h4>${esc(a.name)}</h4><p>${esc(a.benefits)}</p><dl><dt>Who may apply</dt><dd>${esc(a.eligibility)}</dd><dt>Separate steps</dt><dd>${esc(a.application)}</dd><dt>Renewal</dt><dd>${esc(a.renewal)}</dd><dt>Upfront / remaining expenses</dt><dd>${esc(a.upfront)}</dd></dl><small>Award cycle: ${esc(a.cycle)} · Selection is competitive; eligibility thresholds are not acceptance odds.</small>${sourceList(a.sourceIds)}</article>`).join(''):`<p>${t('noAwards')}. Funding is unknown, rather than assumed unavailable or guaranteed.</p>`;}
function openDetail(id){const r=routes.find(r=>r.id===id);if(!r)return;selected=id;$('#detail').innerHTML=`<div class="detail-head"><span class="eyebrow">${esc(r.i.country)}</span>${btn('close',`${t('close')} ×`,'text-btn')}</div><div class="detail-body"><p class="institution">${esc(r.i.name)} · ${esc(r.p.campus)}</p><h2 id="detail-title">${esc(r.p.name)}</h2><p class="route-name">${esc(r.name)}</p><div class="card-meta"><span>After Grade ${r.entryAfter}</span><span>${esc(r.pathway)}</span><span>${esc(r.p.duration)}</span><span>${esc(r.p.credits)}</span></div><section><h3>${t('curriculum')}</h3><p>${esc(r.p.languages.join(', '))}</p><p>${esc(r.p.description)}</p><p>${esc(r.p.curriculum)}</p><p><b>Practical experience:</b> ${esc(r.p.practical)}</p></section><section><h3>${t('eligibility')}</h3><p><b>Applicant:</b> ${esc(r.applicant)}</p><p>${esc(r.eligibility)}</p><p><b>School subjects:</b> ${esc(r.subjects)}</p><p><b>Diploma recognition:</b> ${esc(r.recognition)}</p>${r.prerequisiteRouteIds?.length?`<div class="notice"><b>Regular-offer prerequisite · one available academic route</b>${r.prerequisiteRouteIds.map(id=>btn('detail',`${esc(routes.find(x=>x.id===id)?.name)} →`,'text-btn',`data-id="${id}"`)).join('')}</div>`:''}</section><section><h3>${t('exams')}</h3>${testsHtml(r)}<p class="context-note">Missing or unknown requirements need verification. Published minimum scores only establish eligibility to be considered.</p></section><section><h3>${t('cost')}</h3><h4>${esc(money(r.tuition,lang))}</h4><p>${esc(r.tuition.note)}</p><p><b>${t('fees')}:</b> ${esc(r.mandatoryFees)}</p><p><b>${t('living')}:</b> ${esc(r.living)}</p><p class="context-note">Native currencies are kept separate; no KZT conversion or net-cost estimate is implied.</p></section><section><h3>${t('funding')}</h3>${awardsHtml(r)}</section><section><h3>${t('calendar')} · planned entry ${year}</h3>${r.deadlines.length?r.deadlines.map(deadlineHtml).join(''):'No sourced deadline record. Confirm the selected intake directly.'}${!r.deadlines.some(x=>String(x.cycle).startsWith(String(year))&&x.status!=='historical')?`<div class="notice">${year} cycle dates await confirmation.</div>`:''}</section>${r.questions?.length?`<section><h3>${t('questions')}</h3><ul>${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></section>`:''}<div class="next-detail"><span>↗</span><div><strong>${t('next')}</strong><p>${esc(r.nextAction)}</p></div></div><section><h3>${t('source')}</h3>${sourceList([...(r.p.sourceIds||[]),...r.sourceIds])}</section><section><h3>Suggest a source correction</h3><p>Copy this note for the school’s designated reviewer. No submission destination has been configured.</p><label>Correction or question<textarea id="correction" rows="3" placeholder="Which fact should a reviewer check? Add an official source if you have one."></textarea></label>${btn('correction',t('copy'),'secondary',`data-id="${r.id}"`)}</section><div class="detail-actions">${btn('save',saved.includes(r.id)?t('saved'):t('save'),'secondary',`data-id="${r.id}"`)}${btn('compare',`${compare.includes(r.id)?'✓ ':''}${t('compare')}`,'primary',`data-id="${r.id}"`)}</div></div>`;simplifyDetail();localize($('#detail'));if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
function simplifyDetail(){const body=$('#detail .detail-body');const groups=new Map();for(const section of [...body.querySelectorAll(':scope > section')]){const heading=section.querySelector('h3');if(!heading)continue;const title=heading.textContent;let group=title===t('curriculum')?'About the programme':[t('eligibility'),t('exams'),t('questions')].includes(title)?'How to apply':[t('cost'),t('funding')].includes(title)?'Costs and scholarships':title.startsWith(t('calendar'))?'Deadlines':'Official sources';if(!groups.has(group)){const details=document.createElement('details');details.className='detail-section';const summary=document.createElement('summary');summary.textContent=group;details.append(summary);section.before(details);groups.set(group,details);}const subtitle=document.createElement('h4');subtitle.textContent=title;heading.replaceWith(subtitle);groups.get(group).append(section);}for(const note of body.querySelectorAll('.context-note'))note.remove();}
function comparePage(){const rs=compare.map(id=>routes.find(r=>r.id===id));const rows=[['Applicant route',r=>`${esc(r.name)}<br><small>After Grade ${r.entryAfter} · ${esc(r.pathway)} · ${esc(r.cycle)}</small>`],[t('cost'),r=>`${esc(money(r.tuition,lang))}<p>${esc(r.tuition.note)}</p><small>Fees: ${esc(r.mandatoryFees)}</small>`],[t('funding'),r=>r.awards.length?r.awards.map(a=>`<strong>${esc(coverageLabels[a.coverage])}</strong><p>${esc(a.benefits)}</p><small>Cycle ${esc(a.cycle)}</small>`).join(''):t('noAwards')],[t('exams'),testsHtml],[t('eligibility'),r=>`${esc(r.eligibility)}<p>${esc(r.recognition)}</p><p>Subjects: ${esc(r.subjects)}</p>`],[t('curriculum'),r=>`${esc(r.p.qualification)} · ${esc(r.p.duration)} · ${esc(r.p.credits)}<p>${esc(r.p.curriculum)}</p><small>${esc(r.p.practical)}</small>`],[t('calendar'),r=>r.deadlines.map(x=>`<p>${esc(x.label)}<br><strong>${esc(x.date||'Awaiting publication')}</strong> ${esc(x.time||'')} ${esc(x.timezone||'')}<br><small>${esc(deadlineState(x,year))} · ${esc(x.cycle)}</small></p>`).join('')||'Awaiting confirmation'],[t('next'),r=>esc(r.nextAction)],[t('source'),r=>`<details><summary>${t('source')}</summary>${sourceList([...r.p.sourceIds,...r.sourceIds])}</details>`]];return `<div class="page-body">${pageTitle('compare',t('limit'))}${rs.length?`<div class="compare-scroll" tabindex="0" role="region" aria-label="Programme route comparison"><table><thead><tr><th scope="col">Compare your next steps</th>${rs.map(r=>`<th scope="col"><small>${esc(r.i.name)}</small><h3>${esc(r.p.name)}</h3>${btn('compare',`${t('remove')} ×`,'text-btn',`data-id="${r.id}"`)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${rs.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h2>Find two or three possibilities.</h2><p>Use “Compare” on programme cards, then see their routes side by side.</p>${btn('page',t('explore'),'primary','data-page="explore"')}</div>`}</div>`;}
function latestCheck(){return d.meta?.checked||d.sources.map(s=>s.checked).sort().at(-1);}
function latestCycle(sources){return sources.filter(s=>s.status==='verified').map(s=>s.cycle).filter(c=>/20\d{2}/.test(c)).sort((a,b)=>Math.max(...(b.match(/20\d{2}/g)||[0]).map(Number))-Math.max(...(a.match(/20\d{2}/g)||[0]).map(Number)))[0]||'Undated — cycle confirmation needed';}
function referenceCredits(){return `<details class="all-sources"><summary>Country and subject lists</summary><p>Country and territory list: ISO 3166-1. Subject names adapted and translated from UNESCO-UIS ISCED-F 2013 (2015).</p><p><a href="https://www.iso.org/iso-3166-country-codes.html" target="_blank" rel="noopener noreferrer">ISO 3166-1 ↗</a> · <a href="https://www.uis.unesco.org/sites/default/files/medias/fichiers/2025/04/international-standard-classification-of-education-fields-of-education-and-training-2013-detailed-field-descriptions-2015-en.pdf" target="_blank" rel="noopener noreferrer">UNESCO-UIS ISCED-F 2013 ↗</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/igo/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0 IGO ↗</a></p></details>`;}
function coveragePage(){return `<div class="page-body">${pageTitle('coverage','A growing catalogue, with the evidence kept in view.')}<div class="coverage-summary"><div><strong>${routes.length}</strong><span>applicant routes</span></div><div><strong>${d.programmes.length}</strong><span>programmes</span></div><div><strong>${d.sources.length}</strong><span>official source records</span></div><div><strong>${esc(new Intl.DateTimeFormat(lang,{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(latestCheck()+'T12:00:00Z')))}</strong><span>latest research check</span></div></div><div class="notice">This is an owner-private review edition. Source verification does not settle every applicant’s eligibility. Costs, diploma recognition and future cycles may still need confirmation.</div><div class="coverage-grid">${regions.map(region=>{const rs=routes.filter(r=>r.i.region===region);const sources=[...new Set(rs.flatMap(r=>r.sourceIds))].map(id=>d.sources.find(s=>s.id===id)).filter(Boolean);return `<article><span class="eyebrow">${rs.length?'RESEARCHED':'COVERAGE GAP'}</span><h3>${region}</h3><p><strong>${rs.length}</strong> routes · ${new Set(rs.map(r=>r.p.id)).size} programmes</p><small>${rs.length?`Latest verified cycle: ${esc(latestCycle(sources))}<br>Other source scopes: ${esc([...new Set(sources.map(s=>s.cycle))].join(' · '))}`:'Insufficient verified data. Region supported for future entries.'}</small>${btn('region',`Explore ${region} ↗`,'text-btn',`data-region="${region}"`)}</article>`;}).join('')}</div><section class="editorial"><h2>How to read this catalogue</h2><div class="editorial-grid"><div><h3>Sources keep their own dates</h3><p>Your planned entry year changes the deadline context. It does not turn an older fee schedule or grant call into a new one.</p></div><div><h3>Unknown is a useful answer</h3><p>Unknown tests, diploma equivalence, costs and progression conditions need a check with the institution. They are never confirmed exemptions.</p></div><div><h3>Funding means different things</h3><p>A full scholarship includes tuition and a maintenance or housing package. Tuition-only, partial and conditional aid have separate labels.</p></div></div><h3>Review and corrections</h3><p>A teacher or counsellor should own annual data review. Open a route to copy a correction. The school has not supplied an authorised submission address.</p>${btn('copyCoverage','Copy catalogue review note','secondary')}<h3>Questions awaiting verification</h3><details><summary>${routes.reduce((n,r)=>n+(r.questions?.length||0),0)} route-specific questions</summary>${routes.filter(r=>r.questions?.length).map(r=>`<p><strong>${esc(r.i.name)} · ${esc(r.p.name)}</strong><br>${esc(r.questions.join(' '))}</p>`).join('')}</details><h3>Data & privacy</h3><p>Interface language, planned entry year, bookmarks and comparison choices stay in this browser. No names, marks, birthdates or contacts are collected. Clearing browser storage removes local choices. Official source links open the institution’s website.</p>${btn('clearStorage','Clear my local preferences and bookmarks','text-btn')}</section><details class="all-sources"><summary>All official source records (${d.sources.length})</summary>${sourceList(d.sources.map(s=>s.id))}</details>${referenceCredits()}</div>`;}
function tray(){const rs=compare.map(id=>routes.find(r=>r.id===id));$('#tray').innerHTML=rs.length?`<div class="compare-tray"><span><b>${rs.length} / 3</b> ${t('compare')}<small>${rs.map(r=>esc(r.p.name)).join(' · ')}</small></span><div>${btn('clearCompare',t('clear'),'text-btn')}${btn('page',`${t('compare')} →`,'primary','data-page="compare"')}</div></div>`:'';}
function render({focus=false}={}){header();$('#main').innerHTML=page==='explore'?explorer():page==='shortlist'?shortlistPage():page==='compare'?comparePage():page==='calendar'?calendarPage():coveragePage();$('#main').insertAdjacentHTML('beforeend',`<footer class="simple-footer">${btn('page',t('calendar'),'text-btn','data-page="calendar"')}${btn('page','About','text-btn','data-page="coverage"')}</footer>`);if(page==='explore')renderResults();tray();localize();if(focus){window.scrollTo({top:0});$('#main').focus({preventScroll:true});}}
function go(p){page=p;render({focus:true});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Share it with the designated school reviewer.');}catch{const ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');$('#detail').open?$('#detail').append(ta):document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?'Copied.':'Copy is unavailable in this browser. Select the note from the source details.');}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;e.preventDefault();if(action==='page'||action==='home'){go(el.dataset.page||'explore');}else if(action==='entry'){f.stage=el.dataset.stage;render();$('#catalogue').scrollIntoView({block:'start'});}else if(action==='reset'){f={fields:[],year,costUnknown:true,testUnknown:false};render();$('#catalogue')?.scrollIntoView({block:'start'});}else if(action==='unt'){f={fields:[],year,costUnknown:true,testUnknown:false,stage:'11',region:'Kazakhstan',test:'UNT',testRole:'required'};go('explore');$('#catalogue').scrollIntoView();}else if(action==='after11'){f.stage='11';render();$('#catalogue').scrollIntoView();}else if(action==='region'){f={fields:[],year,costUnknown:true,testUnknown:false,region:el.dataset.region};go('explore');$('#catalogue').scrollIntoView();}else if(action==='save'){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];storeList();const open=$('#detail').open;const y=scrollY;render();window.scrollTo(0,y);if(open)openDetail(id);}else if(action==='compare'){if(!compare.includes(id)&&compare.length===3){toast(t('limit'));return;}compare=addComparison(compare,id);storeList();const open=$('#detail').open;const y=scrollY;render();window.scrollTo(0,y);if(open)openDetail(id);}else if(action==='clearCompare'){compare=[];storeList();render();}else if(action==='detail'){openDetail(id);}else if(action==='close'){$('#detail').close();selected=null;}else if(action==='correction'){const r=routes.find(r=>r.id===id);copy(`${tr('Divergents source review')}\n${tr('Route:')} ${r.id} · ${tr(r.i.name)} · ${tr(r.p.name)}\n${tr('Route cycle:')} ${tr(r.cycle)}; ${tr('planned entry:')} ${year}\n${tr('Question:')} ${$('#correction').value||tr('[add correction]')}\n${tr('Sources:')}\n${[...new Set([...r.p.sourceIds,...r.sourceIds])].map(id=>d.sources.find(s=>s.id===id)?.url).join('\n')}`);}else if(action==='copyCoverage'){copy(tr(`Divergents catalogue review · ${latestCheck()}\n${routes.length} routes; ${d.programmes.length} programmes.\nPlease review outstanding questions, current cycles and official source links before school rollout.`));}else if(action==='clearStorage'){saved=[];compare=[];year=2027;f={fields:[],year,costUnknown:true};storeList();persist();render();toast('Local choices cleared.');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){f.q=e.target.value;renderResults();}else if(e.target.dataset.filter&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT'){f[e.target.dataset.filter]=e.target.value;renderResults();}});
document.addEventListener('change',e=>{if(e.target.id==='lang'){lang=e.target.value;persist();$('#toast').textContent='';render();}else if(e.target.id==='year'){year=+e.target.value||2027;f.year=year;persist();render();}else if(e.target.id==='onlySaved'){onlySaved=e.target.checked;render();}else if(e.target.dataset.field){const field=e.target.dataset.field;f.fields=e.target.checked?[...new Set([...f.fields,field])]:f.fields.filter(x=>x!==field);const y=scrollY;render();window.scrollTo(0,y);}else if(e.target.dataset.filter){const key=e.target.dataset.filter;f[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='region')f.country='';if(key==='country')delete f.region;if(['region','currency'].includes(key)){const y=scrollY;render();window.scrollTo(0,y);}else if(key==='stage')render();else if(key==='subject'){delete f.subject;f.fields=e.target.value?[e.target.value]:[];renderResults();}else renderResults();}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close();});
render();
